package com.gireesh.brokerage.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="portfolio_snapshots", indexes=@Index(name="idx_snapshot_account_time",columnList="account_id,captured_at"))
public class PortfolioSnapshot { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotNull @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="account_id",nullable=false) private TradingAccount account; @NotNull @Column(name="portfolio_value",nullable=false,precision=20,scale=2) private BigDecimal value; @NotNull @Column(nullable=false,precision=20,scale=2) private BigDecimal cash; @NotNull @Column(nullable=false,precision=20,scale=2) private BigDecimal invested; @NotNull @Column(nullable=false,precision=20,scale=2) private BigDecimal realizedPnl; @NotNull @Column(nullable=false,precision=20,scale=2) private BigDecimal unrealizedPnl; @NotNull @Column(nullable=false,precision=20,scale=2) private BigDecimal drawdown; @NotNull @Column(name="captured_at",nullable=false) private LocalDateTime capturedAt; public PortfolioSnapshot(){} public Long getId(){return id;} public TradingAccount getAccount(){return account;} public void setAccount(TradingAccount v){account=v;} public BigDecimal getValue(){return value;} public void setValue(BigDecimal v){value=v;} public BigDecimal getCash(){return cash;} public void setCash(BigDecimal v){cash=v;} public BigDecimal getInvested(){return invested;} public void setInvested(BigDecimal v){invested=v;} public BigDecimal getRealizedPnl(){return realizedPnl;} public void setRealizedPnl(BigDecimal v){realizedPnl=v;} public BigDecimal getUnrealizedPnl(){return unrealizedPnl;} public void setUnrealizedPnl(BigDecimal v){unrealizedPnl=v;} public BigDecimal getDrawdown(){return drawdown;} public void setDrawdown(BigDecimal v){drawdown=v;} public LocalDateTime getCapturedAt(){return capturedAt;} public void setCapturedAt(LocalDateTime v){capturedAt=v;} }
